
-- Handbook v1.14 remediation: convert generic catalogue fillers into distinct study resources.
PRAGMA foreign_keys=OFF;
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'English textcountEnglish text' WHEN 1 THEN 'English text' WHEN 2 THEN 'English text'
      WHEN 3 THEN 'English text' WHEN 4 THEN 'countEnglish text' WHEN 5 THEN 'countEnglish textmanyEnglish textreasoningEnglish text'
      WHEN 6 THEN 'English textmock examEnglish text' WHEN 7 THEN 'incorrect questionsEnglish text' WHEN 8 THEN 'English textpleasetimeEnglish text'
      WHEN 9 THEN 'English text' WHEN 10 THEN 'English textsessionEnglish text' WHEN 11 THEN 'English text'
      WHEN 12 THEN 'studyEnglish text' WHEN 13 THEN 'English text' WHEN 14 THEN 'officialpolicyEnglish text'
      WHEN 15 THEN 'English text' ELSE 'business travelEnglish text' END AS item_type,
    CASE rowid % 19
      WHEN 0 THEN 'English text' WHEN 1 THEN 'English text' WHEN 2 THEN 'English textsample' WHEN 3 THEN 'notEnglish text'
      WHEN 4 THEN 'canatEnglish textdayEnglish text' WHEN 5 THEN 'countEnglish textcontentEnglish textafternotEnglish text' WHEN 6 THEN 'needEnglish textversion' WHEN 7 THEN 'notEnglish textregistrationEnglish text'
      WHEN 8 THEN 'English textbusiness travelEnglish text' WHEN 9 THEN 'needEnglish text' WHEN 10 THEN 'English textnoneEnglish text' WHEN 11 THEN 'English texttimeversionupdate'
      WHEN 12 THEN 'stockhasEnglish textcanalternative' WHEN 13 THEN 'English texttimeasEnglish textworkday' WHEN 14 THEN 'notEnglish textexamaccountinformation'
      WHEN 15 THEN 'canandEnglish text' WHEN 16 THEN 'English textincorrect questionsEnglish text' WHEN 17 THEN 'notEnglish textpleaseEnglish text'
      ELSE 'purchaseEnglish textalreadyhasmaterials' END AS use_scope
  FROM products WHERE product_id LIKE 'prod_exam_prep_noise_%'
)
UPDATE products
SET title = CASE rowid % 5
      WHEN 0 THEN (SELECT item_type || '｜' || use_scope FROM facts WHERE facts.rid=products.rowid)
      WHEN 1 THEN (SELECT use_scope || 'of' || item_type FROM facts WHERE facts.rid=products.rowid)
      WHEN 2 THEN (SELECT item_type || '（English text：' || use_scope || '）' FROM facts WHERE facts.rid=products.rowid)
      WHEN 3 THEN (SELECT 'English text：' || item_type || '；' || use_scope FROM facts WHERE facts.rid=products.rowid)
      ELSE (SELECT item_type || 'studyEnglish text，' || use_scope FROM facts WHERE facts.rid=products.rowid)
    END,
    description = CASE rowid % 7
      WHEN 0 THEN (SELECT item_type || 'English textondayEnglish text；' || use_scope || '，notEnglish textonofficialregistrationorscoreEnglish text。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 1 THEN (SELECT 'productcontentas' || item_type || '。English text：' || use_scope || '；English texthasstock。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 2 THEN (SELECT use_scope || '。English textproductEnglish text' || item_type || '，notEnglish textguaranteed scoreorghostwritingEnglish text。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 3 THEN (SELECT 'English text' || item_type || '；' || use_scope || '，English textuseEnglish text SKU as authority。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 4 THEN (SELECT item_type || 'canEnglish textasEnglish textcandidates。purchaseitemEnglish textis' || use_scope || '，andEnglish textpolicy。' FROM facts WHERE facts.rid=products.rowid)
      WHEN 5 THEN (SELECT 'English textrecord：' || item_type || '。English textversion' || use_scope || '，andofficial guidenotisEnglish textproduct。' FROM facts WHERE facts.rid=products.rowid)
      ELSE (SELECT 'asEnglish text' || item_type || 'whileEnglish text；' || use_scope || '，notEnglish textalternativeEnglish textexamrules。' FROM facts WHERE facts.rid=products.rowid)
    END,
    product_id = replace(product_id, 'prod_exam_prep_noise_', 'prod_study_catalog_')
WHERE product_id LIKE 'prod_exam_prep_noise_%';
PRAGMA foreign_keys=OFF;
UPDATE stocks SET sku_id=replace(sku_id,'sku_exam_prep_noise_','sku_study_catalog_') WHERE sku_id LIKE 'sku_exam_prep_noise_%';
UPDATE skus SET product_id=replace(product_id,'prod_exam_prep_noise_','prod_study_catalog_'), sku_id=replace(sku_id,'sku_exam_prep_noise_','sku_study_catalog_') WHERE sku_id LIKE 'sku_exam_prep_noise_%';
PRAGMA foreign_keys=ON;
